function classify(subject) {
  // TODO: return 'major' | 'minor' | 'patch' | 'none' for one commit subject.
  // Rules: '!' after type/scope OR subject exactly 'BREAKING CHANGE' -> 'major';
  //        'feat' -> 'minor'; 'fix' -> 'patch'; anything else -> 'none'.
  return 'none';
}

var RANK = { none: 0, patch: 1, minor: 2, major: 3 };
function nextVersion(current, commits) {
  var parts = current.split('.').map(Number);
  var top = 'none';
  commits.forEach(function (c) {
    var b = classify(c);
    if (RANK[b] > RANK[top]) top = b;
  });
  if (top === 'major') return (parts[0] + 1) + '.0.0';
  if (top === 'minor') return parts[0] + '.' + (parts[1] + 1) + '.0';
  if (top === 'patch') return parts[0] + '.' + parts[1] + '.' + (parts[2] + 1);
  return current;
}

